-- carry per-artifact licences — see LICENSE and docs/2_canonical_design_spec.md §42.
-- Deploy sig:closed_vocabulary to pg
-- P35.14a (L1 NEW-2 / FM-15): close the sink's open vocabulary. The
-- ontology-owned predicate registry (ontology/vocab/predicates.yaml,
-- 280 predicates x 20 artifact genres) projects into vocab_predicate,
-- vocab_resolution_strategy, the NEW vocab_artifact_genre table and
-- directness_matrix; assertion_quarantine's reason CHECK gains
-- 'unknown_genre'. INSERT-only, ON CONFLICT-safe, no UPDATE/DELETE:
-- pre-existing vocab_predicate rows keep their values (correcting the
-- P19.4 auto-registered defaults is queued hosted work, never an
-- in-place rewrite in this change).

BEGIN;

-- The closed artifact-genre vocabulary the sink stamps evidence artifacts
-- with (claims whose evidence_genre is outside it quarantine unknown_genre).
CREATE TABLE vocab_artifact_genre (
  genre_id   text PRIMARY KEY,
  definition text NOT NULL
);

-- The sink reads this table to gate genres; the materialize role reads the
-- closed vocabulary with the rest of its spine read scope.
GRANT SELECT ON vocab_artifact_genre TO sig_ingest, sig_materialize;

INSERT INTO vocab_artifact_genre (genre_id, definition) VALUES
  ('executed_contract', 'A signed/executed contract document.'),
  ('invoice', 'An invoice or billing record.'),
  ('portal_snapshot', 'A transparency-portal snapshot (e.g. Eyes on Flock).'),
  ('council_minutes', 'Council/board meeting minutes.'),
  ('agency_policy', 'An agency policy or manual.'),
  ('osm_node_set', 'An OpenStreetMap element set (nodes/ways/relations).'),
  ('audit_log', 'An audit or internal-review log.'),
  ('news_article', 'A news article or press report.'),
  ('vendor_default_page', 'A vendor default/documentation page.'),
  ('camera_registry', 'A camera registry dataset or page.'),
  ('connector_run', 'The connector''s own run artifact (fallback genre).'),
  ('agenda_document', 'A meeting agenda document.'),
  ('bill_index', 'A legislative bill index entry.'),
  ('portal_document', 'A document published on a portal.'),
  ('community_map', 'A community-maintained map/dataset.'),
  ('contract', 'A contract document (not confirmed executed).'),
  ('official_statement', 'An official statement or press release.'),
  ('template', 'A template or boilerplate document.'),
  ('subscription', 'A subscription/service listing.'),
  ('recommendation', 'A recommendation listing.')
ON CONFLICT (genre_id) DO NOTHING;

-- Resolution strategies the registry names (§28.4) — vocab_predicate's
-- resolution_strategy column FKs here; before this change the sink
-- auto-inserted them.
INSERT INTO vocab_resolution_strategy (strategy_id, definition) VALUES
  ('authoritative_source_wins', 'The assertion from the highest-reliability source wins (§28.4).'),
  ('interval_union', 'Conflicting intervals are unioned rather than adjudicated (§28.4).'),
  ('latest_observation_wins', 'The most recently observed assertion supersedes earlier ones (§28.4).'),
  ('max_support', 'The value with the greatest independent support wins (§28.4).'),
  ('never_resolve', 'The predicate is never auto-resolved; asserted values coexist (§28.4).')
ON CONFLICT (strategy_id) DO NOTHING;

