  ('count_scope', '1.0.0', 'string', 'literal', 'single', 'Qualifier: the comparability scope a count claim is asserted at (e.g. metro, city_limits, jurisdiction, statewide). P32.3 / SIG-TRUST-004: counts in different scopes answer different questions — they are retained separately and never adjudicated against each other (a scope mismatch is not a contradiction).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/count_scope', 'GLACIAL', 3652, 'never_resolve'),
  ('count_scope_detail', '1.0.0', 'string', 'literal', 'single', 'Qualifier: the refinement inside a count_scope (e.g. privately_owned, partner_agency, agency_operated). Two counts differ on detail at the same scope label are still different questions (P32.3 / SIG-TRUST-004).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/count_scope_detail', 'GLACIAL', 3652, 'never_resolve'),
