  ('constrains_capability', '1.0.0', 'string', 'literal', 'multi', 'A capability slug the legal instrument constrains (§11.14 LegalInstrument surface; the france_belgium connector''s instrument claims).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/constrains_capability', 'SLOW', 1096, 'authoritative_source_wins'),
  ('contract_term_end', '1.0.0', 'edtf', 'literal', 'single', 'The date a procurement contract''s term ends (§11.11 contract facts; the okc_procurement document extractor''s surface).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/contract_term_end', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('effective_to', '1.0.0', 'edtf', 'literal', 'single', 'The date a legal instrument ceases to be in force (§11.14 LegalInstrument; paired with effective_from, distinct from sunset_date which is the legislated expiry).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/effective_to', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('operates_in_country', '1.0.0', 'string', 'literal', 'multi', 'An ISO 3166-1 country code a vendor is asserted to operate in (the coarse_international connector''s curated vendor rows; a vendor-level fact, never a deployment claim).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/operates_in_country', 'SLOW', 1096, 'authoritative_source_wins'),
  ('policy_clause', '1.0.0', 'string', 'literal', 'multi', 'A policy-document clause locator/text the document asserts (§11-flavoured clause-organised policy facts; the okcpd_policy extractor''s surface — a clause locates to a §).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/policy_clause', 'SLOW', 730, 'authoritative_source_wins'),
  ('quantity', '1.0.0', 'integer', 'literal', 'multi', 'A quantity a contract/procurement record states for a product or line item (§11.11 stated quantities — a stated quantity, never a deployed count).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/quantity', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('requires_authorization_of', '1.0.0', 'string', 'literal', 'multi', 'An actor/entity class the legal instrument requires authorisation from or of (§11.14 LegalInstrument surface; the france_belgium connector''s instrument claims).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/requires_authorization_of', 'SLOW', 1096, 'authoritative_source_wins'),
  ('operator_absent', '1.0.0', 'boolean', 'literal', 'single', 'The element carries no `operator`/`operator:wikidata` tag — operator absence as a first-class, countable state (SIG-ONTO-028; the ~116,800-device attribution backlog), never an implicit NULL.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/operator_absent', 'MODERATE', 365, 'latest_observation_wins'),
  ('mfa_required', '1.0.0', 'boolean', 'literal', 'single', 'Whether the deployment''s configuration requires multi-factor authentication (§11.15 ConfigurationState — MFA fails the configuration-cut rule and is a config slot, SIG-ONTO-035).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/mfa_required', 'SLOW', 730, 'authoritative_source_wins'),
  ('retention_days', '1.0.0', 'string', 'literal', 'single', 'The deployment''s configured retention period — an ISO-8601 duration OR an ordinal bucket verbatim (SIG-ONTO-035a: a bucket is never coerced to a midpoint, bound, or point value).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/retention_days', 'SLOW', 730, 'authoritative_source_wins'),
  ('live_stream_permitted_to', '1.0.0', 'string', 'entity_ref', 'single', 'The entity the configuration permits live-stream access to (§11.15 ConfigurationState; an entity_ref carried by the object seam).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/live_stream_permitted_to', 'SLOW', 730, 'authoritative_source_wins'),
  ('third_party_integration', '1.0.0', 'string', 'entity_ref', 'multi', 'A third-party system the deployment''s configuration integrates with (§11.15 ConfigurationState; an entity_ref carried by the object seam).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/third_party_integration', 'SLOW', 730, 'authoritative_source_wins'),
  ('observed_via', '1.0.0', 'string', 'literal', 'multi', 'The channel a configuration fact was observed through — `portal`, `config_screenshot`, `foia_export`, `vendor_statement`, or `contract_term` (§11.15 ConfigurationState provenance vocabulary).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/observed_via', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('distributes_list_to', '1.0.0', 'string', 'entity_ref', 'multi', '§12.3 integration edge: A pushes a watchlist to B for local matching; matches do NOT return to A (one-way list, no feedback — MUST NOT be modelled as federates_search_to, SIG-ONTO-046). Carrier of ''automated alerts'' in the twelve-power-properties map (SIG-ONTO-051).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/distributes_list_to', 'SLOW', 730, 'authoritative_source_wins'),
  ('requests_data_from', '1.0.0', 'string', 'entity_ref', 'multi', '§12.3 integration edge: A can issue per-incident, consent-gated requests to B''s users/devices.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/requests_data_from', 'SLOW', 730, 'authoritative_source_wins'),
  ('authorizes', '1.0.0', 'string', 'entity_ref', 'multi', '§12.3 integration edge: A grants B legal permission to operate a capability; authority moves, no data does.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/authorizes', 'SLOW', 1096, 'authoritative_source_wins'),
  ('replaced_by', '1.0.0', 'string', 'entity_ref', 'single', '§12.3 lifecycle edge: B''s deployment supersedes A''s for the same capability at the same organization (temporal substitution).', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/replaced_by', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('succeeds', '1.0.0', 'string', 'entity_ref', 'single', '§12.3 lifecycle edge: the product/deployment that replaces another for the same capability at the same organization — the forward pair of replaced_by.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/succeeds', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('atlas_category_retired', '1.0.0', 'string', 'literal', 'single', 'A surveillance-technology category retired from the Atlas of Surveillance upstream taxonomy (SIG-ONTO-059): a vocabulary event keyed on the Atlas version at which the category retired, never a world change — a disappearance is "category retired", not a deployment ending.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/atlas_category_retired', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('deployment_ended', '1.0.0', 'string', 'literal', 'single', 'A deployment''s evidenced end in the world (the device set was decommissioned, the programme cancelled) — reserved lifecycle vocabulary named by the Atlas connector but NEVER emitted: an upstream category disappearance is a vocabulary event (atlas_category_retired), not a world event. Registered so the id is governed vocabulary, not an unowned literal.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/deployment_ended', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('osm_element_deleted', '1.0.0', 'string', 'literal', 'single', 'A mapping-event row recorded when a previously-seen OSM element vanishes from a later snapshot (event_class ''mapping_event''): the element left the map, which is NOT evidence the physical asset left the street.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/osm_element_deleted', 'IMMUTABLE', NULL, 'authoritative_source_wins'),
  ('physical_removed_from_street', '1.0.0', 'string', 'literal', 'single', 'The world event of a physical surveillance asset being removed from the street — reserved lifecycle vocabulary named by the OSM connector but never inferred from a map deletion: osm_element_deleted (a mapping event) is the only claim a snapshot diff may emit; removal in the world needs its own evidence. Registered so the id is governed vocabulary, not an unowned literal.', 'https://ontology.sig-project.org/vocab/predicate/1.0.0/physical_removed_from_street', 'IMMUTABLE', NULL, 'authoritative_source_wins')
ON CONFLICT (predicate_id) DO NOTHING;

